using System.Text; using MediatR; using InventorySystem.Application.Features.Stock.Commands; using InventorySystem.Application.Features.Stock.Queries; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace InventorySystem.API.Controllers;
[ApiController][Route("api/stock")] public class StockController(IMediator m):ControllerBase { [HttpPost("movement")][Authorize(Roles="Admin,Manager,Cashier")] public async Task<IActionResult> Add(AddStockCommand c)=>Ok(new{id=await m.Send(c)}); [HttpGet("low-stock")][Authorize] public async Task<IActionResult> Low()=>Ok(await m.Send(new GetLowStockQuery())); [HttpGet("movements")][Authorize] public async Task<IActionResult> Movements([FromQuery]GetStockMovementsQuery q)=>Ok(await m.Send(q)); [HttpGet("movements/export")][Authorize] public async Task<IActionResult> ExportMovements([FromQuery]ExportMovementsQuery q)=>File(new UTF8Encoding(true).GetBytes(await m.Send(q)),"text/csv","movements.csv"); }
